	query := `
	SELECT episode_id, session_id, content, snippet(episodes_fts, 2, '>', '', '...', 64), files_touched, outcomes, date 
	FROM episodes_fts 
	WHERE episodes_fts MATCH ?
	ORDER BY bm25(episodes_fts)
	`
