	var results []EpisodeRecord
	for rows.Next() {
		var r EpisodeRecord
		var dateStr string
		if err := rows.Scan(&r.EpisodeID, &r.SessionID, &r.Content, &r.Snippet, &r.FilesTouched, &r.Outcomes, &dateStr); err != nil {
